effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec2 sz = vec2(size);
  if (square) sz = vec2(size * (acScreenSize.y / max(acScreenSize.x, 1.0)), size);
  vec2 grid = acScreenSize / max(sz, vec2(1.0));
  vec2 p = (floor(uv * grid) + 0.5) / grid;
  vec4 a = texture2DCv(inputImg.texture, uv);
  vec4 b = texture2DCv(inputImg.texture, p);
  gl_FragColor = mix(a, b, mixAmt);
}
